import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  const disposables = {
    geometries: [],
    materials: [],
    timelines: [],
    primitiveCleanups: []
  };

  const colors = config.intent?.visualSpec?.colors || {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  const gradientStops = config.intent?.visualSpec?.colors?.gradientStops || [
    { at: 0, hex: '#0b0b10' },
    { at: 0.65, hex: '#101017' },
    { at: 1, hex: '#16161d' }
  ];

  // Convert hex string to TSL vec3
  const hexToVec3 = (hex) => {
    const num = parseInt(hex.substring(1), 16);
    return vec3(
      ((num >> 16) & 255) / 255,
      ((num >> 8) & 255) / 255,
      (num & 255) / 255
    );
  };

  // Backdrop plane with radial gradient
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const color0 = hexToVec3(gradientStops[0].hex);
  const color1 = hexToVec3(gradientStops[1].hex);
  const color2 = hexToVec3(gradientStops[2].hex);

  const u = uv();
  const gradientNode = mix(
    mix(color0, color1, smoothstep(0, 0.65, u.y)),
    color2,
    smoothstep(0.65, 1, u.y)
  );

  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = gradientNode;
  const backdropPlane = new THREE.Mesh(backdropGeom, backdropMat);
  backdropPlane.position.z = -3;
  group.add(backdropPlane);
  disposables.geometries.push(backdropGeom);
  disposables.materials.push(backdropMat);

  // Fog
  group.fog = new THREE.Fog(parseInt(colors.background.substring(1), 16), 5, 11);

  let primaryGear = null;
  let secondaryGear = null;
  let gearRotationTimeline = null;

  // Load gear mesh and setup rotation
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const loadedGear = gltf.scene.clone();

    // Normalize to 1.6-unit diameter
    const box = new THREE.Box3().setFromObject(loadedGear);
    const size = box.getSize(new THREE.Vector3());
    const dia = Math.max(size.x, size.y);
    loadedGear.scale.multiplyScalar(1.6 / dia);
    loadedGear.position.set(0, 0, 0);

    primaryGear = loadedGear;
    group.add(primaryGear);

    // Secondary gear: 0.9-unit scaled, positioned at [1.15, 0.35, -0.1]
    secondaryGear = primaryGear.clone();
    secondaryGear.scale.multiplyScalar(0.9 / 1.6);
    secondaryGear.position.set(1.15, 0.35, -0.1);
    group.add(secondaryGear);

    // Phase-locked rotation: primary 0.08 rad/s, secondary -0.142 rad/s
    const period1 = (2 * Math.PI) / 0.08;
    const period2 = (2 * Math.PI) / 0.142;

    gearRotationTimeline = gsap.timeline({ repeat: -1 });
    gearRotationTimeline.to(primaryGear.rotation, {
      z: Math.PI * 2,
      duration: period1,
      ease: 'none'
    }, 0);
    gearRotationTimeline.to(secondaryGear.rotation, {
      z: -Math.PI * 2,
      duration: period2,
      ease: 'none'
    }, 0);

    if (gearRotationTimeline) {
      disposables.timelines.push(gearRotationTimeline);
    }
  });

  // Jewel pivot sphere
  const jewelGeom = new THREE.IcosahedronGeometry(0.12, 32);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.accent),
    transmission: 0.6,
    ior: 1.76,
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.8
  });
  const jewelSphere = new THREE.Mesh(jewelGeom, jewelMat);
  group.add(jewelSphere);
  disposables.geometries.push(jewelGeom);
  disposables.materials.push(jewelMat);

  // Arbor shafts (ink cylinders through hubs)
  const shaftGeom = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.ink),
    metalness: 0.7,
    roughness: 0.5
  });

  const shaft1 = new THREE.Mesh(shaftGeom, shaftMat);
  group.add(shaft1);

  const shaft2 = new THREE.Mesh(shaftGeom, shaftMat);
  shaft2.position.set(1.15, 0.35, -0.1);
  group.add(shaft2);

  disposables.geometries.push(shaftGeom);
  disposables.materials.push(shaftMat);

  // Contact shadow ellipse
  const shadowGeom = new THREE.PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.transparent = true;
  shadowMat.opacity = 0.5;

  const shadowPlane = new THREE.Mesh(shadowGeom, shadowMat);
  shadowPlane.position.y = -1.2;
  shadowPlane.rotation.x = Math.PI / 2;
  group.add(shadowPlane);
  disposables.geometries.push(shadowGeom);
  disposables.materials.push(shadowMat);

  // Headline text
  const headlineText = ctx.fontAtlas.createText('The going train', {
    fontSize: 68,
    color: colors.paper,
    align: 'center'
  });
  headlineText.position.set(0, -1.7, 0.5);
  group.add(headlineText);

  // Caption text
  const captionText = ctx.fontAtlas.createText('34 COMPONENTS / HAND-FINISHED', {
    fontSize: 18,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 1.44
  });
  captionText.position.set(0, -2.1, 0.5);
  group.add(captionText);

  // Apply orbit cinematic primitive
  const primitives = config.cinematicPrimitives || [];
  const orbitPrim = primitives.find(p => p.name === 'orbit');

  if (orbitPrim) {
    const result = ctx.primitives['orbit'](group, orbitPrim.params || { speed: 0.08, radius: 0.2 });
    if (result && result.cleanup) {
      disposables.primitiveCleanups.push(result.cleanup);
    }
  }

  // Cleanup function
  group.userData.cleanup = function() {
    disposables.timelines.forEach(t => t && t.kill && t.kill());
    disposables.primitiveCleanups.forEach(c => c && c());
    disposables.geometries.forEach(g => g && g.dispose && g.dispose());
    disposables.materials.forEach(m => m && m.dispose && m.dispose());
  };

  return group;
}
